    import time

    LANGUAGE_WRAPPER = 'Consider the exponential equation:\n\n{base}^{4{step}x} - ({base}^{[u_1]} + {base}^{[u_2]} + {base}^{[u_3]} + {base}^{[u_4]}) {base}^{3{step}x} + ({base}^{[u_12]} + {base}^{[u_13]} + {base}^{[u_14]} + {base}^{[u_23]} + {base}^{[u_24]} + {base}^{[u_34]}) {base}^{2{step}x} - ({base}^{[u_123]} + {base}^{[u_124]} + {base}^{[u_134]} + {base}^{[u_234]}) {base}^{{step}x} + {base}^{[u_1234]} = 0.\n\nThis equation has exactly four real solutions. If their sum is m/n in lowest terms, find m+n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate a harder quartic-factorable exponential equation instance.
# We choose base in [2..9], a moderately large step, and four distinct u_i.
bases = [2,3,4,5,6,7,8,9]
base = rng.choice(bases)
# Step should be reasonably large to avoid trivial reduced fraction
step = rng.randint(60, 240)
# Pick four distinct shifts u_i
# Ensure spread and distinctness for nontrivial structure
candidates = list(range(2, 21))
rng.shuffle(candidates)
u_vals = sorted(candidates[:4])
u_1, u_2, u_3, u_4 = u_vals
# Compute sums needed for wrapper
u_12 = u_1 + u_2
u_13 = u_1 + u_3
u_14 = u_1 + u_4
u_23 = u_2 + u_3
u_24 = u_2 + u_4
u_34 = u_3 + u_4
u_123 = u_1 + u_2 + u_3
u_124 = u_1 + u_2 + u_4
u_134 = u_1 + u_3 + u_4
u_234 = u_2 + u_3 + u_4
u_1234 = u_1 + u_2 + u_3 + u_4
return {
    'base': base,
    'step': step,
    'u_1': u_1,
    'u_2': u_2,
    'u_3': u_3,
