    if get('u_34') != u3+u4: return (False, None)
    if get('u_123') != u1+u2+u3: return (False, None)
    if get('u_124') != u1+u2+u4: return (False, None)
    if get('u_134') != u1+u3+u4: return (False, None)
    if get('u_234') != u2+u3+u4: return (False, None)
    if get('u_1234') != u1+u2+u3+u4: return (False, None)
    # Solutions in t are exactly base^{u_i}, all positive, so solutions in x are u_i/step.
    # Sum of solutions = (u1+u2+u3+u4)/step.
    num = u1 + u2 + u3 + u4
    den = step
    # Reduce to lowest terms
    import math
    g = math.gcd(num, den)
    num //= g
    den //= g
    answer = num + den
